package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Iterator;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ArrayRealVector_getNorm_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testGetNormWithEmptyVector() {
        // An empty vector has a sum of 0, sqrt(0) = 0
        ArrayRealVector vector = new ArrayRealVector(new double[]{});
        Assert.assertEquals(0.0, vector.getNorm(), EPSILON);
    }

    @Test
    public void testGetNormWithZeroVector() {
        // Vector with all zeros
        ArrayRealVector vector = new ArrayRealVector(new double[]{0.0, 0.0, 0.0});
        Assert.assertEquals(0.0, vector.getNorm(), EPSILON);
    }

    @Test
    public void testGetNormWithPositiveValues() {
        // Standard Euclidean norm: sqrt(3^2 + 4^2) = sqrt(9 + 16) = 5
        ArrayRealVector vector = new ArrayRealVector(new double[]{3.0, 4.0});
        Assert.assertEquals(5.0, vector.getNorm(), EPSILON);
    }

    @Test
    public void testGetNormWithNegativeValues() {
        // Squares of negatives are positive: sqrt((-3)^2 + (-4)^2) = 5
        ArrayRealVector vector = new ArrayRealVector(new double[]{-3.0, -4.0});
        Assert.assertEquals(5.0, vector.getNorm(), EPSILON);
    }

    @Test
    public void testGetNormWithMixedValues() {
        // sqrt(1^2 + (-2)^2 + 2^2) = sqrt(1 + 4 + 4) = 3
        ArrayRealVector vector = new ArrayRealVector(new double[]{1.0, -2.0, 2.0});
        Assert.assertEquals(3.0, vector.getNorm(), EPSILON);
    }

    @Test
    public void testGetNormWithSingleElement() {
        ArrayRealVector vector = new ArrayRealVector(new double[]{7.5});
        Assert.assertEquals(7.5, vector.getNorm(), EPSILON);
    }

    @Test
    public void testGetNormWithLargeValues() {
        // Testing potential overflow or precision handling
        double val = 1e10;
        ArrayRealVector vector = new ArrayRealVector(new double[]{val, val});
        // sqrt(val^2 + val^2) = val * sqrt(2)
        double expected = val * Math.sqrt(2.0);
        Assert.assertEquals(expected, vector.getNorm(), EPSILON * val);
    }

    @Test
    public void testGetNormWithSmallValues() {
        double val = 1e-10;
        ArrayRealVector vector = new ArrayRealVector(new double[]{val, val});
        double expected = val * Math.sqrt(2.0);
        Assert.assertEquals(expected, vector.getNorm(), EPSILON);
    }
}
